strategy_source:character:
function (ctx, params) 
{
    if (isTRUE(params$restart_probe) && isTRUE(restart_once$armed) && identical(ctx$ts_utc, "2020-01-03T16:00:00Z")) {
        restart_once$armed <- FALSE
        stop("a0 planned restart witness", call. = FALSE)
    }
    target <- ctx$hold()
    if (ctx$ts_utc >= "2020-01-03T16:00:00Z" && "AAA" %in% names(target)) 
        target[["AAA"]] <- 0
    target
}
